static struct buffer_head *udf_bread(struct super_block *sb, sector_t block)
{
	struct buffer_head *bh = sb_getblk(sb, block);

	if (!bh)
		return NULL;

	if (buffer_uptodate(bh))
		return bh;

	if (trylock_buffer(bh)) {
		if (buffer_uptodate(bh)) {
			unlock_buffer(bh);
			return bh;
		}
		get_bh(bh);
		bh->b_end_io = end_buffer_read_sync;
		submit_bh(REQ_OP_READ, 0, bh);
	}

	if (wait_on_bit_io(&bh->b_state, BH_Lock, TASK_INTERRUPTIBLE)) {
		brelse(bh);
		return NULL;
	}

	if (buffer_uptodate(bh))
		return bh;

	brelse(bh);
	return NULL;
}

